<template>
  <div class="masking-view">
    <div class="head"><div><div class="eyebrow">ADMIN / COMPLIANCE</div><h1>数据脱敏与合规</h1><p>查询、历史、分析和导出默认只使用脱敏结果。</p></div><button ref="createButton" class="btn primary with-icon" @click="openCreate"><Plus :size="15" aria-hidden="true" />新增规则</button></div>
    <div v-if="error" class="alert error" role="alert"><CircleAlert :size="16" aria-hidden="true" />{{ error }}</div><div v-if="notice" class="alert success" role="status"><CircleCheck :size="16" aria-hidden="true" />{{ notice }}</div>
    <div class="policy"><strong>全局基线</strong><span>{{ policy.enabled ? '脱敏已启用' : '脱敏已关闭' }}</span><span>{{ policy.heuristic_enabled ? '字段名与值格式识别已启用' : '启发式识别已关闭' }}</span><span>显式“保留原值”规则可覆盖内置识别</span></div>
    <section class="panel builtin-panel" aria-labelledby="builtin-title"><div class="section-head"><div><h2 id="builtin-title">系统内置规则</h2><p>这些规则不存储在工作空间规则表中，但会作用于所有查询出口。</p></div><span class="baseline-badge">{{ policy.heuristic_enabled ? '运行中' : '已关闭' }}</span></div><div v-if="loading" class="empty compact">正在加载内置策略…</div><table v-else class="rules builtin-rules"><thead><tr><th>识别来源</th><th>类型</th><th>匹配范围</th><th>说明</th></tr></thead><tbody><tr v-for="(item, index) in policy.builtins" :key="`${item.source}-${item.data_kind}-${index}`"><td>{{ item.source === 'column_name' ? '字段名' : '值格式' }}</td><td>{{ kindLabel(item.data_kind) }}</td><td><code>{{ item.patterns?.length ? item.patterns.join('、') : '格式校验' }}</code></td><td>{{ item.description }}</td></tr></tbody></table></section>
    <section class="panel" aria-labelledby="explicit-title"><div class="section-head"><div><h2 id="explicit-title">工作空间显式规则</h2><p>按优先级覆盖内置策略；需要展示明文时，请新增启用的“保留原值”规则。</p></div></div><div v-if="loading" class="empty">正在加载脱敏规则…</div><table v-else class="rules"><thead><tr><th>字段匹配</th><th>类型</th><th>策略</th><th>优先级</th><th>状态</th><th>说明</th><th>操作</th></tr></thead><tbody><tr v-for="item in rules" :key="item.id"><td><code>{{ item.column_pattern }}</code></td><td>{{ kindLabel(item.data_kind) }}</td><td>{{ strategyLabel(item.strategy) }}</td><td>{{ item.priority }}</td><td><button class="status" :class="{ on: item.enabled }" @click="toggle(item)">{{ item.enabled ? '已启用' : '已停用' }}</button></td><td>{{ item.description || '—' }}</td><td class="ops"><button @click="openEdit(item)">编辑</button><button class="danger" @click="remove(item)">删除</button></td></tr></tbody></table><div v-if="!loading && !rules.length" class="empty">暂无显式规则；上方系统内置规则仍会生效。</div></section>
    <div v-if="modal.open" class="modal-mask" @click.self="closeModal" @keydown.esc.stop="closeModal"><div ref="modalElement" class="modal" role="dialog" aria-modal="true" :aria-labelledby="modalTitleId"><div class="modal-title"><h2 :id="modalTitleId">{{ modal.id ? '编辑' : '新增' }}脱敏规则</h2><button aria-label="关闭脱敏规则弹层" @click="closeModal"><X :size="18" aria-hidden="true" /></button></div><p>支持精确字段名和 * 通配符，例如 *.phone；“保留原值”用于显式覆盖内置识别。</p><form @submit.prevent="save"><label>字段匹配<input ref="firstInput" v-model.trim="form.column_pattern" required placeholder="例如：*.phone" /></label><div class="form-row"><label>数据类型<select v-model="form.data_kind"><option value="generic">通用</option><option value="phone">手机号</option><option value="email">邮箱</option><option value="id_card">身份证</option><option value="bank_card">银行卡</option><option value="name">姓名</option></select></label><label>策略<select v-model="form.strategy"><option value="mask">格式化掩码</option><option value="hash">不可逆哈希</option><option value="keep_last4">仅保留后四位</option><option value="null">置空</option><option value="keep">保留原值（覆盖内置）</option></select></label><label>优先级<input v-model.number="form.priority" type="number" min="0" max="10000" /></label></div><label>说明<textarea v-model.trim="form.description" rows="3"></textarea></label><label class="check"><input v-model="form.enabled" type="checkbox" /> 启用规则</label><div class="foot"><button type="button" class="btn" @click="closeModal">取消</button><button class="btn primary" :disabled="saving">{{ saving ? '保存中…' : '保存' }}</button></div></form></div></div>
  </div>
</template>

<script setup>
import { nextTick, onMounted, reactive, ref } from "vue";
import { CircleAlert, CircleCheck, Plus, X } from "@lucide/vue";
import { requestJson } from "../utils/http.js";
import { confirmDialog } from "../composables/appDialog.js";
const API = "/api/admin/meta/masking/rules";
const rules = ref([]), loading = ref(false), saving = ref(false), error = ref(""), notice = ref("");
const policy = ref({ enabled: true, heuristic_enabled: true, default_strategy: "mask", builtins: [] });
const modal = reactive({ open: false, id: null });
const createButton = ref(null), modalElement = ref(null), firstInput = ref(null);
const modalTitleId = "masking-rule-title";
let modalTrigger = null;
const form = reactive({ column_pattern: "", data_kind: "generic", strategy: "mask", enabled: true, priority: 100, description: "" });
async function request(path = "", options = {}) { return requestJson(`${API}${path}`, options, "脱敏规则请求失败"); }
async function load() { loading.value = true; error.value = ""; try { const [items, policyBody] = await Promise.all([request(), requestJson("/api/admin/meta/masking/policy", {}, "脱敏策略加载失败")]); rules.value = items; policy.value = policyBody; } catch (e) { error.value = e.message || "规则加载失败"; } finally { loading.value = false; } }
function reset() { Object.assign(form, { column_pattern: "", data_kind: "generic", strategy: "mask", enabled: true, priority: 100, description: "" }); }
async function focusModal() { await nextTick(); firstInput.value?.focus(); }
function openCreate() { modalTrigger = document.activeElement; reset(); modal.id = null; modal.open = true; focusModal(); }
function openEdit(item) { modalTrigger = document.activeElement; Object.assign(form, item); modal.id = item.id; modal.open = true; focusModal(); }
function closeModal() { modal.open = false; nextTick(() => modalTrigger?.focus?.()); }
async function save() { saving.value = true; error.value = ""; try { await request(modal.id ? `/${modal.id}` : "", { method: modal.id ? "PATCH" : "POST", body: JSON.stringify(form) }); closeModal(); await load(); notice.value = "规则已保存，后续查询立即生效。"; } catch (e) { error.value = e.message || "保存失败"; } finally { saving.value = false; } }
async function toggle(item) { try { await request(`/${item.id}`, { method: "PATCH", body: JSON.stringify({ ...item, enabled: !item.enabled }) }); await load(); } catch (e) { error.value = e.message || "状态更新失败"; } }
async function remove(item) {
  const confirmed = await confirmDialog({
    title: "删除脱敏规则？",
    message: `字段匹配“${item.column_pattern}”将不再应用此自定义脱敏策略。`,
    confirmLabel: "删除规则",
    tone: "danger",
  });
  if (!confirmed) return;
  try {
    await request(`/${item.id}`, { method: "DELETE" });
    await load();
    notice.value = "规则已删除。";
  } catch (e) {
    error.value = e.message || "删除失败";
  }
}
function kindLabel(value) { return ({ generic: "通用", phone: "手机号", email: "邮箱", id_card: "身份证", bank_card: "银行卡", name: "姓名" }[value] || value); }
function strategyLabel(value) { return ({ mask: "格式化掩码", hash: "不可逆哈希", keep_last4: "保留后四位", null: "置空", keep: "保留原值" }[value] || value); }
onMounted(load);
</script>

<style scoped>
.masking-view{flex:1;overflow:auto;padding:30px 34px 55px;background:#f7f8fa;color:var(--da-text)}.head{max-width:1360px;margin:0 auto 22px;display:flex;align-items:flex-end;justify-content:space-between;gap:20px}.eyebrow{color:var(--da-accent);font-size:11px;font-weight:700;letter-spacing:.14em}h1{margin:6px 0 0;font-size:26px}p{margin:8px 0 0;color:var(--da-text-muted);font-size:13px}.btn{border:1px solid var(--da-border);border-radius:8px;background:#fff;color:var(--da-text-secondary);padding:9px 14px;font-size:13px;cursor:pointer}.btn.with-icon,.alert{display:flex;align-items:center;gap:7px}.btn.primary{background:var(--da-accent);border-color:var(--da-accent);color:#fff}.alert,.policy,.panel{max-width:1360px;margin:0 auto 14px}.alert{padding:10px 14px;border-radius:8px;font-size:13px}.alert.error{background:#fff3f1;border:1px solid #f0c5bf;color:#bd3b2c}.alert.success{background:#f0fbf4;border:1px solid #b9e2c8;color:#287b4a}.policy{display:flex;flex-wrap:wrap;gap:15px;padding:13px 15px;border:1px solid #cfe0f4;border-radius:9px;background:#f4f8fd;color:var(--da-text-secondary);font-size:12px}.policy strong{color:var(--da-accent)}.panel{padding:20px;border:1px solid var(--da-border-light);border-radius:12px;background:#fff;box-shadow:0 3px 14px rgba(31,35,41,.03)}.rules{width:100%;border-collapse:collapse;font-size:13px}.rules th,.rules td{padding:13px 10px;border-bottom:1px solid var(--da-border-light);text-align:left;vertical-align:top}.rules th{color:var(--da-text-muted);font-size:12px;font-weight:500}.rules code{color:#5379a6}.status,.ops button{border:0;background:transparent;color:var(--da-accent);font:inherit;font-size:12px;cursor:pointer}.status.on{color:#2e9a60}.danger{color:var(--da-danger)!important}.ops{white-space:nowrap}.empty{padding:70px 20px;text-align:center;color:var(--da-text-muted);font-size:13px}.modal-mask{position:fixed;z-index:20;inset:0;display:grid;place-items:center;padding:20px;background:rgba(31,35,41,.35)}.modal{width:min(620px,100%);padding:23px;border-radius:13px;background:#fff;box-shadow:0 18px 60px rgba(31,35,41,.22)}.modal-title{display:flex;justify-content:space-between;align-items:center}.modal-title h2{margin:0;font-size:18px}.modal-title button{width:34px;height:34px;display:grid;place-items:center;border:0;border-radius:9px;background:var(--da-bg-soft);color:var(--da-text-muted);cursor:pointer}.modal label{display:block;margin:14px 0;color:var(--da-text-secondary);font-size:12px}.modal input:not([type=checkbox]),.modal select,.modal textarea{display:block;width:100%;box-sizing:border-box;margin-top:6px;padding:9px 11px;border:1px solid var(--da-border);border-radius:7px;outline:0;color:var(--da-text);font:inherit;font-size:13px}.form-row{display:grid;grid-template-columns:1.2fr 1.2fr .7fr;gap:10px}.check{display:flex!important;align-items:center;gap:8px}.check input{width:15px;height:15px}.foot{display:flex;justify-content:flex-end;gap:8px;margin-top:20px;padding-top:15px;border-top:1px solid var(--da-border-light)}@media(max-width:850px){.masking-view{padding:22px 15px 40px}.head{display:block}.head .btn{margin-top:15px}.panel{overflow:auto}.rules{min-width:800px}.form-row{grid-template-columns:1fr}}
.section-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:10px}.section-head h2{margin:0;font-size:17px}.section-head p{margin-top:5px}.baseline-badge{padding:5px 9px;border-radius:999px;background:#e9f7ef;color:#287b4a;font-size:12px}.builtin-panel{background:#fbfdff}.builtin-rules code{display:block;max-width:620px;white-space:normal;line-height:1.65}.empty.compact{min-height:80px;padding:30px 20px}
/* visual refresh */
.masking-view{padding:38px 34px 64px;background:transparent}.head{max-width:1420px;margin-bottom:25px}.eyebrow{font-size:10px;letter-spacing:.17em}h1{margin-top:7px;font-size:29px;letter-spacing:-.04em}.btn{min-height:38px;border-radius:10px;font-weight:550;transition:.15s}.btn:hover:not(:disabled){border-color:var(--da-accent);color:var(--da-accent);background:var(--da-accent-soft)}.btn.primary{box-shadow:0 7px 16px rgba(52,120,246,.17)}.btn.primary:hover:not(:disabled){color:#fff;background:var(--da-accent-hover)}.alert,.policy,.panel{max-width:1420px}.alert,.policy{border-radius:11px}.panel{padding:22px;border-color:var(--da-border-light);border-radius:16px;box-shadow:var(--da-shadow-sm)}.rules th{padding-top:10px;text-transform:uppercase;letter-spacing:.04em}.rules tbody tr{transition:.12s}.rules tbody tr:hover{background:#fbfcfe}.rules tbody tr:nth-child(even){background:rgba(244,247,251,.45)}.status,.ops button{min-height:29px;padding:4px 7px;border-radius:7px}.status:hover,.ops button:hover{background:var(--da-accent-soft)}.empty{min-height:280px}.modal-mask{backdrop-filter:blur(4px)}.modal{border:1px solid rgba(255,255,255,.75);border-radius:18px;box-shadow:var(--da-shadow-lg)}.modal input:not([type=checkbox]),.modal select,.modal textarea{border-radius:9px;background:#fbfcfe}.modal input:focus,.modal select:focus,.modal textarea:focus{border-color:var(--da-accent);background:#fff;box-shadow:0 0 0 3px var(--da-accent-soft)}@media(max-width:850px){.masking-view{padding:25px 15px 44px}.panel{padding:14px}}
</style>
